#!/usr/bin/env bash
# After changing texts in the code: updates the template (languages/wptb.pot) and adds new strings to the
# translations (languages/wptb-<locale>.po), which are then translated by hand or in Poedit.
# The files WordPress loads (.l10n.php, .json) are generated by bin/build-zip.sh.
# `bin/i18n.sh --check` only checks that every string of the code is translated (for CI), changing nothing.
# Needs WP-CLI: `wp`, or WP_CLI=/path/to/wp-cli.phar.
set -euo pipefail
cd "$(dirname "$0")/.."
source bin/lib-wp-cli.sh

pot=languages/wptb.pot
[[ "${1:-}" == --check ]] && pot=$(mktemp).pot
wp i18n make-pot . "$pot" --slug=wp-toolbox --domain=wptb \
	--include="wp-toolbox.php,src,assets/src" --exclude="assets/src/settings/test" \
	--headers='{"Report-Msgid-Bugs-To":"https://github.com/miji-dev/wp-toolbox/issues"}' --quiet
if [[ "${1:-}" == --check ]]; then
	exec php bin/check-translations.php "$pot"
fi
for po in languages/wptb-*.po; do
	if command -v msgmerge >/dev/null; then
		# gettext keeps translations of changed texts as "fuzzy" (to review) instead of dropping them like WP-CLI
		msgmerge --update --backup=none --no-wrap --quiet "$po" languages/wptb.pot
	else
		wp i18n update-po languages/wptb.pot "$po" --quiet
	fi
done
php bin/check-translations.php "$pot" || echo "Translate the strings above in languages/*.po."
